BEGIN;

-- Lifecycle actors need only their exact action authority; reading remains separately permissioned.
CREATE OR REPLACE FUNCTION refs_transition_recurring_schedule(p_tenant uuid,p_entity uuid,p_schedule uuid,p_action text,p_revision bigint,p_reason text,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE actor text:=refs_current_actor();action text:=upper(p_action);idem idempotency_receipt;s recurring_schedule;next_status text;permission text;payload jsonb;BEGIN
 IF actor IS NULL OR action NOT IN('SUBMIT','APPROVE','PAUSE','RESUME') OR p_revision IS NULL OR p_revision<0 OR length(btrim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 2000 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_recurring_schedule_transition_hash(p_tenant,p_entity,p_schedule,action,p_revision,p_reason) THEN RAISE EXCEPTION 'Invalid recurring schedule transition command' USING ERRCODE='22023'; END IF; permission:=CASE action WHEN 'SUBMIT' THEN 'RECURRING.SCHEDULE.SUBMIT' WHEN 'APPROVE' THEN 'RECURRING.SCHEDULE.APPROVE' ELSE 'RECURRING.SCHEDULE.MANAGE' END;PERFORM refs_assert_scope(p_tenant,p_entity,permission);INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'RECURRING_SCHEDULE_'||action||':'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='RECURRING_SCHEDULE_'||action||':'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Recurring schedule idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 SELECT * INTO s FROM recurring_schedule WHERE tenant_id=p_tenant AND entity_id=p_entity AND recurring_schedule_id=p_schedule FOR UPDATE;next_status:=CASE action WHEN 'SUBMIT' THEN 'PENDING_APPROVAL' WHEN 'APPROVE' THEN 'ACTIVE' WHEN 'PAUSE' THEN 'PAUSED' ELSE 'ACTIVE' END;IF NOT FOUND OR s.revision<>p_revision OR(action='SUBMIT' AND(s.status<>'DRAFT' OR actor=s.created_by))OR(action='APPROVE' AND(s.status<>'PENDING_APPROVAL' OR actor IN(s.created_by,s.submitted_by)))OR(action='PAUSE' AND(s.status<>'ACTIVE' OR actor=s.created_by))OR(action='RESUME' AND(s.status<>'PAUSED' OR actor=s.created_by)) THEN RAISE EXCEPTION 'Recurring schedule state, revision, or separation of duties conflict' USING ERRCODE='40001';END IF; INSERT INTO recurring_schedule_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,p_schedule,action);UPDATE recurring_schedule SET status=next_status,revision=revision+1,submitted_by=CASE WHEN action='SUBMIT' THEN actor ELSE submitted_by END,submitted_at=CASE WHEN action='SUBMIT' THEN clock_timestamp() ELSE submitted_at END,approved_by=CASE WHEN action='APPROVE' THEN actor ELSE approved_by END,approved_at=CASE WHEN action='APPROVE' THEN clock_timestamp() ELSE approved_at END WHERE tenant_id=p_tenant AND recurring_schedule_id=p_schedule;DELETE FROM recurring_schedule_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND recurring_schedule_id=p_schedule AND operation=action;payload:=refs_recurring_schedule_payload(p_tenant,p_entity,p_schedule)||jsonb_build_object('idempotent',false);INSERT INTO recurring_schedule_history(recurring_schedule_id,tenant_id,from_status,to_status,action,revision,actor_id,reason,event_hash) VALUES(p_schedule,p_tenant,s.status,next_status,action,s.revision+1,actor,btrim(p_reason),refs_jsonb_hash(payload));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'RECURRING_SCHEDULE_'||action,'RECURRING_SCHEDULE',p_schedule,action,actor,'USER',permission,p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(payload),btrim(p_reason),payload);INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'RECURRING_SCHEDULE',p_schedule,'RECURRING_SCHEDULE_'||action,payload,refs_jsonb_hash(payload));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

CREATE OR REPLACE FUNCTION refs_run_due_recurring_schedules(p_tenant uuid,p_entity uuid,p_as_of date,p_limit integer,p_idempotency_key text,p_request_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$ DECLARE actor text:=refs_current_actor();idem idempotency_receipt;s recurring_schedule;r recurring_schedule_run;run_id uuid;period uuid;journal uuid;payload jsonb;rows jsonb:='[]'::jsonb;reason text:='Scheduler run due date';drafts integer:=0;failures integer:=0;attempted integer:=0;BEGIN
 IF actor IS NULL OR p_as_of IS NULL OR p_limit NOT BETWEEN 1 AND 100 OR length(coalesce(p_idempotency_key,'')) NOT BETWEEN 8 AND 200 OR p_request_hash IS DISTINCT FROM refs_recurring_schedule_run_hash(p_tenant,p_entity,p_as_of,p_limit) THEN RAISE EXCEPTION 'Invalid recurring schedule run command' USING ERRCODE='22023'; END IF;PERFORM refs_assert_scope(p_tenant,p_entity,'RECURRING.SCHEDULE.RUN');INSERT INTO idempotency_receipt(tenant_id,operation_scope,idempotency_key,request_hash,status,actor_id) VALUES(p_tenant,'RECURRING_SCHEDULE_RUN:'||p_entity,p_idempotency_key,p_request_hash,'IN_PROGRESS',actor) ON CONFLICT DO NOTHING;SELECT * INTO idem FROM idempotency_receipt WHERE tenant_id=p_tenant AND operation_scope='RECURRING_SCHEDULE_RUN:'||p_entity AND idempotency_key=p_idempotency_key FOR UPDATE;IF idem.actor_id IS DISTINCT FROM actor OR idem.request_hash IS DISTINCT FROM p_request_hash THEN RAISE EXCEPTION 'Recurring scheduler idempotency conflict' USING ERRCODE='23505';END IF;IF idem.status='SUCCEEDED' THEN RETURN idem.response_body||jsonb_build_object('idempotent',true);END IF;
 FOR s IN SELECT * FROM recurring_schedule WHERE tenant_id=p_tenant AND entity_id=p_entity AND status='ACTIVE' AND next_due_on<=p_as_of AND(ends_on IS NULL OR next_due_on<=ends_on) ORDER BY next_due_on,recurring_schedule_id LIMIT p_limit FOR UPDATE SKIP LOCKED LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('RECURRING_SCHEDULE_RUN:'||s.recurring_schedule_id::text||':'||s.next_due_on::text,0));
  INSERT INTO recurring_schedule_run(tenant_id,entity_id,recurring_schedule_id,due_on,status) VALUES(p_tenant,p_entity,s.recurring_schedule_id,s.next_due_on,'RUNNING') ON CONFLICT(tenant_id,recurring_schedule_id,due_on) DO NOTHING RETURNING recurring_schedule_run_id INTO run_id;
  IF run_id IS NULL THEN SELECT * INTO r FROM recurring_schedule_run WHERE tenant_id=p_tenant AND recurring_schedule_id=s.recurring_schedule_id AND due_on=s.next_due_on FOR UPDATE;IF r.status='FAILED' THEN run_id:=r.recurring_schedule_run_id;INSERT INTO recurring_schedule_run_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,run_id);UPDATE recurring_schedule_run SET status='RUNNING',attempt_count=attempt_count+1,failure_code=NULL,completed_at=NULL WHERE recurring_schedule_run_id=run_id;DELETE FROM recurring_schedule_run_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND recurring_schedule_run_id=run_id;ELSE CONTINUE;END IF;END IF;
  attempted:=attempted+1; BEGIN
   SELECT period_id INTO period FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND ledger_code='PRIMARY' AND status='OPEN' AND s.next_due_on BETWEEN starts_on AND ends_on FOR SHARE;IF period IS NULL THEN RAISE EXCEPTION 'No open period for due date' USING ERRCODE='23514';END IF;
   journal:=gen_random_uuid();INSERT INTO journal_entry(journal_entry_id,tenant_id,entity_id,period_id,journal_number,journal_type,status,journal_date,currency,description,created_by) VALUES(journal,p_tenant,p_entity,period,left(s.journal_prefix||'-'||replace(s.recurring_schedule_id::text,'-','')||'-'||to_char(s.next_due_on,'YYYYMMDD'),120),'AUTO','DRAFT',s.next_due_on,s.currency,'Recurring schedule: '||s.name,actor);
   INSERT INTO journal_line(tenant_id,entity_id,period_id,journal_entry_id,line_no,account_code,debit_amount,credit_amount,member_ref,description,dimensions) SELECT p_tenant,p_entity,period,journal,(x->>'lineNo')::integer,x->>'accountCode',(x->>'debitAmount')::numeric,(x->>'creditAmount')::numeric,NULLIF(x->>'memberRef',''),NULLIF(x->>'description',''),x->'dimensions' FROM jsonb_array_elements(s.template_lines) x;
   INSERT INTO recurring_schedule_run_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,run_id);UPDATE recurring_schedule_run SET status='DRAFT_CREATED',journal_entry_id=journal,completed_at=clock_timestamp() WHERE recurring_schedule_run_id=run_id;DELETE FROM recurring_schedule_run_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND recurring_schedule_run_id=run_id;
   INSERT INTO recurring_schedule_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,s.recurring_schedule_id,'RUN');UPDATE recurring_schedule SET next_due_on=refs_recurring_schedule_next_due(next_due_on,frequency),last_run_at=clock_timestamp(),revision=revision+1 WHERE recurring_schedule_id=s.recurring_schedule_id;DELETE FROM recurring_schedule_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND recurring_schedule_id=s.recurring_schedule_id AND operation='RUN';INSERT INTO recurring_schedule_history(recurring_schedule_id,tenant_id,from_status,to_status,action,revision,actor_id,reason,event_hash) VALUES(s.recurring_schedule_id,p_tenant,'ACTIVE','ACTIVE','RUN',s.revision+1,actor,reason,refs_jsonb_hash(jsonb_build_object('run_id',run_id,'journal_entry_id',journal,'status','DRAFT_CREATED')));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'RECURRING_SCHEDULE_DRAFT_CREATED','RECURRING_SCHEDULE_RUN',run_id,'RUN',actor,'USER','RECURRING.SCHEDULE.RUN',p_idempotency_key,p_idempotency_key,p_idempotency_key,refs_jsonb_hash(jsonb_build_object('journal_entry_id',journal,'status','DRAFT')),reason,jsonb_build_object('recurring_schedule_id',s.recurring_schedule_id,'journal_entry_id',journal,'journal_status','DRAFT'));INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'RECURRING_SCHEDULE_RUN',run_id,'RECURRING_SCHEDULE_DRAFT_CREATED',jsonb_build_object('recurring_schedule_id',s.recurring_schedule_id,'journal_entry_id',journal,'journal_status','DRAFT'),refs_jsonb_hash(jsonb_build_object('recurring_schedule_id',s.recurring_schedule_id,'journal_entry_id',journal,'journal_status','DRAFT')));rows:=rows||jsonb_build_array(jsonb_build_object('recurring_schedule_run_id',run_id,'recurring_schedule_id',s.recurring_schedule_id,'due_on',s.next_due_on,'status','DRAFT_CREATED','attempt_count','1','journal_entry_id',journal,'failure_code',NULL));drafts:=drafts+1;
  EXCEPTION WHEN OTHERS THEN
   INSERT INTO recurring_schedule_run_gate VALUES(pg_backend_pid(),txid_current(),p_tenant,run_id);UPDATE recurring_schedule_run SET status='FAILED',failure_code='RECURRING_DRAFT_MATERIALIZATION_FAILED',completed_at=clock_timestamp() WHERE recurring_schedule_run_id=run_id;DELETE FROM recurring_schedule_run_gate WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current() AND tenant_id=p_tenant AND recurring_schedule_run_id=run_id;INSERT INTO recurring_schedule_exception(tenant_id,entity_id,recurring_schedule_run_id,exception_code,exception_hash) VALUES(p_tenant,p_entity,run_id,'RECURRING_DRAFT_MATERIALIZATION_FAILED',refs_jsonb_hash(jsonb_build_object('schedule_id',s.recurring_schedule_id,'due_on',s.next_due_on,'code','RECURRING_DRAFT_MATERIALIZATION_FAILED')));INSERT INTO audit_event(tenant_id,entity_id,event_type,object_type,object_id,action,actor_id,actor_type,permission_used,request_id,correlation_id,idempotency_key,after_hash,reason,metadata) VALUES(p_tenant,p_entity,'RECURRING_SCHEDULE_DRAFT_FAILED','RECURRING_SCHEDULE_RUN',run_id,'RUN',actor,'USER','RECURRING.SCHEDULE.RUN',p_idempotency_key,p_idempotency_key,p_idempotency_key,NULL,reason,jsonb_build_object('recurring_schedule_id',s.recurring_schedule_id,'failure_code','RECURRING_DRAFT_MATERIALIZATION_FAILED'));INSERT INTO outbox_event(tenant_id,entity_id,aggregate_type,aggregate_id,event_type,payload,payload_hash) VALUES(p_tenant,p_entity,'RECURRING_SCHEDULE_RUN',run_id,'RECURRING_SCHEDULE_DRAFT_FAILED',jsonb_build_object('recurring_schedule_id',s.recurring_schedule_id,'failure_code','RECURRING_DRAFT_MATERIALIZATION_FAILED'),refs_jsonb_hash(jsonb_build_object('recurring_schedule_id',s.recurring_schedule_id,'failure_code','RECURRING_DRAFT_MATERIALIZATION_FAILED')));rows:=rows||jsonb_build_array(jsonb_build_object('recurring_schedule_run_id',run_id,'recurring_schedule_id',s.recurring_schedule_id,'due_on',s.next_due_on,'status','FAILED','attempt_count',(SELECT attempt_count::text FROM recurring_schedule_run WHERE recurring_schedule_run_id=run_id),'journal_entry_id',NULL,'failure_code','RECURRING_DRAFT_MATERIALIZATION_FAILED'));failures:=failures+1;
  END;
 END LOOP;
 payload:=jsonb_build_object('schema_version','RECURRING_SCHEDULE_RUN_BATCH_V1','tenant_id',p_tenant,'entity_id',p_entity,'as_of_date',p_as_of,'attempted_count',attempted::text,'draft_created_count',drafts::text,'failed_count',failures::text,'runs',rows,'idempotent',false,'action_flags',jsonb_build_object('can_post',false));UPDATE idempotency_receipt SET status='SUCCEEDED',response_status=200,response_body=payload,completed_at=clock_timestamp() WHERE idempotency_receipt_id=idem.idempotency_receipt_id;RETURN payload;
END;$$;

REVOKE ALL ON FUNCTION refs_transition_recurring_schedule(uuid,uuid,uuid,text,bigint,text,text,text),refs_run_due_recurring_schedules(uuid,uuid,date,integer,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION refs_transition_recurring_schedule(uuid,uuid,uuid,text,bigint,text,text,text),refs_run_due_recurring_schedules(uuid,uuid,date,integer,text,text) TO refs_app;

COMMIT;
